def compute(vars):
    bell_wireline_capex = vars["v1"]
    bce_capex = vars["v2"]

    if bce_capex == 0:
        return None

    percentage = (bell_wireline_capex / bce_capex) * 100

    return {
        "value": percentage,
        "trace": {
            "bell_wireline_capex": bell_wireline_capex,
            "bce_capex": bce_capex,
            "ratio": bell_wireline_capex / bce_capex,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
